import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.BZk_B2cc.js";const g=JSON.parse('{"title":"F3: End-to-End Cryptographic Ride Lifecycle & OTP Handshake","description":"","frontmatter":{},"headers":[],"relativePath":"features/F3-otp-ride-lifecycle.md","filePath":"features/F3-otp-ride-lifecycle.md"}'),s={name:"features/F3-otp-ride-lifecycle.md"};function r(d,e,o,c,h,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="f3-end-to-end-cryptographic-ride-lifecycle-otp-handshake" tabindex="-1">F3: End-to-End Cryptographic Ride Lifecycle &amp; OTP Handshake <a class="header-anchor" href="#f3-end-to-end-cryptographic-ride-lifecycle-otp-handshake" aria-label="Permalink to &quot;F3: End-to-End Cryptographic Ride Lifecycle &amp; OTP Handshake&quot;">​</a></h1><h2 id="_1-description-state-machine" tabindex="-1">1. Description &amp; State Machine <a class="header-anchor" href="#_1-description-state-machine" aria-label="Permalink to &quot;1. Description &amp; State Machine&quot;">​</a></h2><p>To prevent ride hijacking and ensure the correct passenger enters the vehicle, the system generates a random 4-digit OTP during ride creation (<code>ride.service.js</code>). The OTP is revealed only to the rider. When the captain arrives, they must enter this OTP on their interface (<code>ConfirmRidePopUp.jsx</code>) before the backend transitions the ride from <code>accepted</code> to <code>ongoing</code>.</p><h2 id="_2-state-transition-diagram" tabindex="-1">2. State Transition Diagram <a class="header-anchor" href="#_2-state-transition-diagram" aria-label="Permalink to &quot;2. State Transition Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [*] --&gt; pending: Rider requests ride</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pending --&gt; accepted: Captain accepts ride via Socket/REST</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    accepted --&gt; ongoing: Captain enters valid 4-digit OTP</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ongoing --&gt; completed: Captain finishes ride at destination</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pending --&gt; cancelled: Rider or Captain cancels</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    completed --&gt; [*]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;To eliminate passenger mismatch and fraudulent ride claims, I built a cryptographically secured OTP verification handshake. When a ride is created, the server generates a 4-digit numeric code stored alongside the ride document and transmits it only to the rider&#39;s device. When the driver arrives, they enter the code into their app, which hits the <code>/rides/start-ride</code> endpoint. The server verifies the OTP against the database and, upon a match, transitions the ride status to &#39;ongoing&#39; while notifying both parties via WebSockets. If an incorrect OTP is entered, the attempt is rejected with an HTTP 400 error, ensuring the vehicle never moves under a false state.&quot;</p>`,7)])])}const m=a(s,[["render",r]]);export{g as __pageData,m as default};
